// Servidor: una función común con un efecto (cuenta las veces que se ejecutó).
let ejecuciones = 0;
function marcarEntregado(id) { ejecuciones++; return { id, estado: 'ENTREGADO' }; }

// "Red" de juguete: pasa bytes; el tercer mensaje de respuesta se pierde.
let respuestas = 0;
async function red(bytesPedido) {
  const pedido = JSON.parse(bytesPedido);                 // stub del servidor: bytes -> argumentos
  const resultado = marcarEntregado(pedido.id);           // la función real
  const bytesRespuesta = JSON.stringify(resultado);       // resultado -> bytes
  respuestas++;
  if (respuestas === 2) return new Promise(() => {});     // la respuesta se pierde: nunca llega
  return bytesRespuesta;
}

// Stub del cliente: parece una función local, pero por dentro serializa, envía y espera con plazo.
function conPlazo(promesa, ms) {
  return Promise.race([promesa, new Promise((_, rej) => setTimeout(() => rej(new Error('DEADLINE_EXCEEDED')), ms))]);
}
async function marcarEntregadoRemoto(id) {
  const bytes = JSON.stringify({ id });                   // argumentos -> bytes
  const resp = await conPlazo(red(bytes), 100);           // enviar y esperar, pero no para siempre
  return JSON.parse(resp);                                // bytes -> resultado
}

console.log('local :', marcarEntregado('D-1'));
ejecuciones = 0; // desde acá contamos solo lo que pasa por la red
for (const id of ['D-2', 'D-3']) {
  try { console.log('remoto:', await marcarEntregadoRemoto(id)); }
  catch (e) { console.log('remoto:', id, 'falló con', e.message); }
}
console.log('pedidos que mandó el cliente: 2 | ejecuciones reales en el servidor:', ejecuciones);

syntax = "proto3";
package despachos.v1;

service Despachos {
  // Una pregunta, una respuesta.
  rpc ObtenerDespacho (PedidoDespacho) returns (Despacho);
  // Una pregunta, muchas respuestas a lo largo del tiempo.
  rpc SeguirDespacho (PedidoDespacho) returns (stream Posicion);
}

message PedidoDespacho {
  string id = 1;
}

message Despacho {
  string id = 1;
  string estado = 2;
  string destino = 3;
  uint32 bultos = 4;
}

message Posicion {
  string id = 1;
  double lat = 2;
  double lng = 3;
}

