// Codificación a mano de un mensaje Protobuf: cada campo es etiqueta + valor.
// etiqueta = (número_de_campo << 3) | tipo_de_cable   (0 = entero variable, 2 = bytes con largo)
const enc = new TextEncoder();
const hex = (u8) => [...u8].map((b) => b.toString(16).padStart(2, '0')).join(' ');

function varint(n) {                       // 7 bits por byte; el bit alto dice «sigue»
  const out = [];
  while (n > 127) { out.push((n & 127) | 128); n = Math.floor(n / 128); }
  out.push(n);
  return out;
}
function campoTexto(num, texto) {
  const b = enc.encode(texto);
  return [(num << 3) | 2, ...varint(b.length), ...b];
}
function campoEntero(num, n) {
  return [(num << 3) | 0, ...varint(n)];
}

// message Despacho { string id = 1; string estado = 2; string destino = 3; uint32 bultos = 4; }
const cuerpo = [
  ...campoTexto(1, 'D-1042'),
  ...campoTexto(2, 'EN_RUTA'),
  ...campoTexto(3, 'Rosario'),
  ...campoEntero(4, 12),
];
console.log('mensaje :', hex(cuerpo));
console.log('tamaño  :', cuerpo.length, 'bytes');

// Dentro de gRPC se le antepone un prefijo de 5 bytes: 1 de «comprimido» + 4 de largo.
const largo = cuerpo.length;
const prefijo = [0, (largo >>> 24) & 255, (largo >>> 16) & 255, (largo >>> 8) & 255, largo & 255];
console.log('con prefijo gRPC:', hex([...prefijo, ...cuerpo]));

const json = JSON.stringify({ id: 'D-1042', estado: 'EN_RUTA', destino: 'Rosario', bultos: 12 });
console.log('el mismo dato en JSON:', enc.encode(json).length, 'bytes');
