import { initTRPC, TRPCError } from '@trpc/server';
import { z } from 'zod';

const t = initTRPC.create();

export const appRouter = t.router({
  despacho: t.router({
    obtener: t.procedure
      .input(z.object({ id: z.string() }))
      .query(({ input }) => {
        const d = DESPACHOS[input.id];
        if (!d) throw new TRPCError({ code: 'NOT_FOUND', message: 'no existe el despacho ' + input.id });
        return d;           // { id, estado, destino, bultos }
      }),
  }),
});

export type AppRouter = typeof appRouter;   // ESTO es el contrato: un tipo, no un archivo aparte

